import React, { useState, useEffect } from 'react'
import Navbar from '../components/Navbar'
import Footer from '../components/Footer'
import Card from '../components/Card'
import Carousel from '../components/Carousel'

export default function Home() {

    const [foodCat, setfoodCat] = useState([]);
    const [foodItem, setfoodItem] = useState([]);

    const loadData = async () => {
        try {
            let response = await fetch("http://localhost:5000/api/data", {
                method: "POST",
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            response = await response.json();
            // console.log(response.food_items, response.foodCategory);
            setfoodItem(response.food_items);
            setfoodCat(response.foodCategory);
        } catch (error) {
            console.error("Failed to load data:", error);
        }
    }

    useEffect(() => {
        loadData();
    }, []
    );

    return (
        <div>

            <div> <Navbar /></div>
            <div> <Carousel /> </div>
            <div className='container' >
                {
                    Array.isArray(foodCat) && foodCat.length > 0
                        ? foodCat.map((data, idx) => 
                        (<div className='row mb-3'>
                            <div key={data._id} className='fs-3 m-3'>
                                {data.CategoryName}
                            </div>
                            {
                                Array.isArray(foodItem) && foodItem.length > 0
                                    // foodItem !== []
                                    ?
                                    foodItem.filter((item) => item.CategoryName == data.CategoryName)
                                        .map(filterItems => {
                                            return (
                                                <div key={filterItems._id} className='col-12 col-md-6 col-lg-3'>
                                                    <Card />

                                                </div>
                                            )
                                        })
                                    : <div> No such data found

                                    </div>}

                            <hr />
                        </div>
                        )

                        )
                        : ""
                }

                <Card />
            </div>

            <div> <Footer /> </div>

        </div>
    )
}
